/// Core 下发的一路拉流。`url` 已由 Core 按本端能力挑好协议。
public struct LivePlayRequest {
    public let streamName: String
    public let url: String
    /// main / aux / audio
    public let streamType: String
    public let publisherUserId: String
    /// 起播时这一路的声音是否先关掉。之后用 setPlaybackMuted 改音量。
    public let muted: Bool
    /// 本次进课代际。流名在成员不上下台时跨会话不变，只按流名去重会把上一次
    /// 会话遗留的播放器当成「已在播」而只换地址，续上的却是已销毁的渲染视图，
    /// 表现为重进课后永远不出画。代际变了必须整路重建。
    public let playbackId: Int64
    public let epoch: Int64

    public init(
        streamName: String,
        url: String,
        streamType: String,
        publisherUserId: String,
        muted: Bool,
        epoch: Int64 = 0,
        playbackId: Int64
    ) {
        self.streamName = streamName
        self.url = url
        self.streamType = streamType
        self.publisherUserId = publisherUserId
        self.muted = muted
        self.playbackId = playbackId
        self.epoch = epoch
    }
}

/// 与 Core `live_play_stop_reason` 对齐的停播原因，三端同名
public enum LivePlayStopReason {
    public static let renderViewMissing = "render_view_missing"
    public static let vendorLoading = "vendor_loading"
    public static let hostStop = "host_stop"
    public static let firstFrameTimeout = "first_frame_timeout"
}

public enum LiveAdapterEvent {
    case playPrepared(streamName: String)
    case observation(streamName: String, playbackId: Int64, kind: String, code: Int32?, message: String?)
    /// `recoverable` 为 true 表示厂商仍在自行重连，Core 不应摘掉这一路。
    /// `reason` 取 `LivePlayStopReason` 的稳定枚举，只进遥测，用于区分
    /// 「等渲染视图」与「厂商缓冲中」这两类看起来一样的卡顿。
    case playStopped(streamName: String, recoverable: Bool, reason: String)
    case playFailed(streamName: String, message: String)
    case sei(streamName: String, serverMs: Int64)
    case statistics(streamName: String, playbackId: Int64, metrics: [String: Int64])
}

/// 腾讯云直播 License 状态。未加载时播放器会直接拒绝播放，表现为黑屏而无业务错误。
public enum LicenceState: Equatable {
    case unset
    /// 配了空值。集成方漏填时走这里，与「加载失败」区分开
    case missing
    case loading
    case loaded
    /// `result` 与 `reason` 直接透传厂商回调，便于照着腾讯文档查错因
    case failed(result: Int32, reason: String)

    public var canPlay: Bool { self == .loaded }

    /// 遥测维度：压成稳定枚举字符串，不要把 reason 原文当维度
    public var telemetryValue: String {
        switch self {
        case .unset: return "unset"
        case .missing: return "missing"
        case .loading: return "loading"
        case .loaded: return "loaded"
        case .failed: return "failed"
        }
    }

    var report: (loaded: Bool, state: String, code: Int32, message: String) {
        switch self {
        case .unset: return (false, "unset", 0, "")
        case .missing: return (false, "missing", 0, "")
        case .loading: return (false, "loading", 0, "")
        case .loaded: return (true, "loaded", 0, "")
        case .failed(let result, let reason): return (false, "failed", result, reason)
        }
    }

    /// Core 展开成明确的 License 失败说明。格式：`edusdk.live_licence:<state>:<code>:<reason>`。
    var failureToken: String {
        let value = report
        return "edusdk.live_licence:\(value.state):\(value.code):\(value.message)"
    }
}

/// License 必须在创建任何播放器**之前**设置，且加载是异步的，
/// 所以这里把结果回调出去供遥测与降级判断，而不是设完就当成功。
#if canImport(TXLiteAVSDK_TRTC)
public final class LiveLicence {
    public static let shared = LiveLicence()
    // Written and consumed only on main, where the vendor player owns its render views.
    public private(set) var current: LicenceState = .unset
    private let worker = DispatchQueue(label: "edusdk.live.licence")
    private weak var owner: AnyObject?
    private var listener: ((LicenceState) -> Void)?
    private var observer: Observer?

    private struct Report: Decodable {
        let state: String
        let code: Int32
        let message: String
        func value() throws -> LicenceState {
            switch state {
            case "loading": return .loading
            case "loaded": return .loaded
            case "missing": return .missing
            case "failed": return .failed(result: code, reason: message)
            default: throw NSError(domain: "edusdk.live.licence", code: -1,
                userInfo: [NSLocalizedDescriptionKey: "Invalid native licence state"])
            }
        }
    }
    private struct Decision: Decodable {
        let generation: UInt64
        let configure: Bool
        let report: Report
    }
    private final class Observer: NSObject, V2TXLivePremierObserver {
        let receive: (Int32, String) -> Void
        init(receive: @escaping (Int32, String) -> Void) { self.receive = receive }
        func onLicenceLoaded(_ result: Int32, reason: String) { receive(result, reason) }
    }

    public func apply(url: String, key: String, owner: AnyObject, onResult: @escaping (LicenceState) -> Void) {
        worker.async {
            self.owner = owner
            self.listener = onResult
            do {
                let license = TencentLiveLicense.resolve(url: url, key: key)
                let decision = try JSONDecoder().decode(Decision.self, from: Data(
                    nativeLiveLicencePrepare(url: license.url, key: license.key).utf8))
                try self.publish(decision.report)
                if decision.configure {
                    let observer = Observer { [weak self] code, message in
                        guard let self else { return }
                        self.worker.async {
                            do {
                                guard let result = nativeLiveLicenceComplete(generation: decision.generation, code: code, message: message) else { return }
                                try self.publish(JSONDecoder().decode(Report.self, from: Data(result.utf8)))
                            } catch { self.publishBoundaryFailure(error) }
                        }
                    }
                    self.observer = observer
                    V2TXLivePremier.setObserver(observer)
                    V2TXLivePremier.setLicence(license.url, key: license.key)
                }
            } catch { self.publishBoundaryFailure(error) }
        }
    }

    public func detach(owner: AnyObject) {
        worker.async {
            if self.owner === owner { self.owner = nil; self.listener = nil }
        }
    }

    private func publish(_ report: Report) throws {
        let value = try report.value()
        DispatchQueue.main.async { self.current = value }
        if owner != nil { listener?(value) }
    }
    private func publishBoundaryFailure(_ error: Error) {
        let value = LicenceState.failed(result: -1, reason: "Native licence bridge failed: \(error.localizedDescription)")
        DispatchQueue.main.async { self.current = value }
        if owner != nil { listener?(value) }
    }
}

/// iOS 端多路直播播放适配器。
///
/// 台下一堂课同时播多路（每位台上成员一路主流、屏幕共享一路辅流、一路纯音频混流），
/// 所以这里按 `streamName` 维护多个 `V2TXLivePlayer` 实例，而不是单例换源。
public final class TencentLiveIosAdapter: NSObject {
    private final class Entry {
        let player: V2TXLivePlayer
        var url: String
        var view: UIView?
        let epoch: Int64
        let request: LivePlayRequest
        var muted: Bool

        init(
            player: V2TXLivePlayer,
            url: String,
            view: UIView?,
            epoch: Int64,
            request: LivePlayRequest
        ) {
            self.player = player
            self.url = url
            self.view = view
            self.epoch = epoch
            self.request = request
            self.muted = request.muted
        }
    }

    private var classroomPlaybackAllowed = true // native output gain, main thread only
    private static let playbackVolumeSilent: UInt = 0
    private static let playbackVolumeFull: UInt = 100
    /// 纯音频路没有画面，不需要等渲染视图
    private static let audioStreamType = "audio"
    private final class Pending {
        let request: LivePlayRequest
        init(request: LivePlayRequest) { self.request = request }
    }

    private var players: [String: Entry] = [:]
    /// 等渲染视图的路。stopPlay / 重建 / 视图到位时作废
    private var pendingStarts: [String: Pending] = [:]
    /// Observer 回调只带 player，这里反查流名，避免给每一路各建一个 observer 类
    private var streamNames: [ObjectIdentifier: String] = [:]
    private let onEvent: (LiveAdapterEvent) -> Void
    private let resolveView: (String) -> UIView?

    public init(
        onEvent: @escaping (LiveAdapterEvent) -> Void,
        resolveView: @escaping (String) -> UIView?
    ) {
        self.onEvent = onEvent
        self.resolveView = resolveView
    }

    /// 起播一路。同代际同名重复调用按换源处理；代际变了整路重建
    public func startPlay(_ request: LivePlayRequest) {
        guard Thread.isMainThread else {
            DispatchQueue.main.async { self.startPlay(request) }
            return
        }
        // Core 区分加载中的等待和真实授权失败，并在授权就绪后重发应播流。
        guard LiveLicence.shared.current.canPlay else {
            onEvent(.playFailed(
                streamName: request.streamName,
                message: LiveLicence.shared.current.failureToken
            ))
            return
        }
        if let existing = players[request.streamName] {
            // 同代际内的重复下发才是续签换源；跨代际说明上一轮会话的播放器还在，
            // 它绑的视图已经销毁，只换地址换不回画面。
            if existing.request.playbackId == request.playbackId {
                updateCredential(streamName: request.streamName, url: request.url)
                return
            }
            stopPlay(streamName: request.streamName)
        }
        // 视频路必须等到渲染视图：没有视图时起播只出声不出画，而 Core 看到
        // playing 已置位就不会再下发，这一路会一直黑着。
        let view = resolveView(request.streamName)
        if view == nil, request.streamType != Self.audioStreamType {
            waitForRenderView(request)
            return
        }
        pendingStarts.removeValue(forKey: request.streamName)
        let player = V2TXLivePlayer()
        streamNames[ObjectIdentifier(player)] = request.streamName
        player.setObserver(self)
        player.enableReceiveSeiMessage(true, payloadType: 5)
        if let view { player.setRenderView(view) }
        // 视频路在混音模式下必须静音，否则 N 路声音会叠在一起
        let volumeCode = player.setPlayoutVolume((request.muted || !classroomPlaybackAllowed) ? Self.playbackVolumeSilent : Self.playbackVolumeFull)
        guard volumeCode.rawValue == 0 else {
            player.setObserver(nil)
            streamNames.removeValue(forKey: ObjectIdentifier(player))
            onEvent(.playFailed(streamName: request.streamName, message: "Live initial volume failed: \(volumeCode.rawValue)"))
            return
        }
        let code = player.startLivePlay(request.url)
        guard code.rawValue == 0 /* V2TXLiveCode: success */ else {
            player.setObserver(nil)
            streamNames.removeValue(forKey: ObjectIdentifier(player))
            onEvent(.playFailed(
                streamName: request.streamName,
                message: "edusdk.live_player:start:\(code.rawValue):"
            ))
            return
        }
        let entry = Entry(
            player: player,
            url: request.url,
            view: view,
            epoch: request.epoch,
            request: request
        )
        players[request.streamName] = entry
        onEvent(.playPrepared(streamName: request.streamName))
    }

    /// View attachment wakes this request; Core owns its deadline and retries.
    private func waitForRenderView(_ request: LivePlayRequest) {
        pendingStarts[request.streamName] = Pending(request: request)
        onEvent(.playStopped(streamName: request.streamName, recoverable: true,
                             reason: LivePlayStopReason.renderViewMissing))
    }

    /// 续签后原地换地址，不重建播放器，避免画面闪断
    public func updateCredential(streamName: String, url: String) {
        guard Thread.isMainThread else {
            DispatchQueue.main.async { self.updateCredential(streamName: streamName, url: url) }
            return
        }
        guard let entry = players[streamName] else {
            reportMissingPlayer(streamName: streamName)
            return
        }
        guard entry.url != url else { return }
        entry.url = url
        _ = entry.player.startLivePlay(url)
    }

    /// 只改音量。播放器继续解码，不新建实例。
    public func setPlaybackMuted(streamName: String, muted: Bool, playbackId: Int64) throws -> Bool {
        guard Thread.isMainThread, playbackId > 0 else {
            throw NSError(domain: "EduSDK.Live", code: -1, userInfo: [NSLocalizedDescriptionKey: "Live mute requires a player instance on the main thread"])
        }
        guard let entry = players[streamName] else {
            if pendingStarts[streamName] == nil {
                onEvent(.observation(streamName: streamName, playbackId: playbackId, kind: "error", code: nil, message: "Live mute target is missing"))
            }
            return false
        }
        guard entry.request.playbackId == playbackId else { return false }
        entry.muted = muted
        let code = entry.player.setPlayoutVolume((muted || !classroomPlaybackAllowed) ? Self.playbackVolumeSilent : Self.playbackVolumeFull)
        guard code.rawValue == 0 else {
            throw NSError(domain: "EduSDK.Live", code: Int(code.rawValue), userInfo: [NSLocalizedDescriptionKey: "Live volume update failed: \(code.rawValue)"])
        }
        return true
    }

    /// Independent output gain; preserves each source's Core mute choice.
    public func setClassroomPlaybackAllowed(_ allowed: Bool) throws {
        precondition(Thread.isMainThread)
        classroomPlaybackAllowed = allowed
        var failures: [String] = []
        for (name, entry) in players {
            let code = entry.player.setPlayoutVolume((entry.muted || !allowed) ? Self.playbackVolumeSilent : Self.playbackVolumeFull)
            if code.rawValue != 0 { failures.append("\(name): live output gain failed \(code.rawValue)") }
        }
        if !failures.isEmpty {
            throw NSError(domain: "EduSDK.Live", code: -1, userInfo: [NSLocalizedDescriptionKey: failures.joined(separator: "; ")])
        }
    }

    public func stopAllPlayConfirmed() throws {
        guard Thread.isMainThread else {
            throw NSError(domain: "EduSDK.Live", code: -1, userInfo: [NSLocalizedDescriptionKey: "Live cleanup must execute on the main thread"])
        }
        pendingStarts.removeAll()
        var failure: Int?
        for (name, entry) in Array(players) {
            _ = entry.player.setPlayoutVolume(Self.playbackVolumeSilent)
            let code = entry.player.stopPlay()
            if code.rawValue == 0 {
                entry.player.setObserver(nil)
                streamNames.removeValue(forKey: ObjectIdentifier(entry.player))
                players.removeValue(forKey: name)
            } else if failure == nil {
                failure = Int(code.rawValue)
            }
        }
        if let failure {
            throw NSError(domain: "EduSDK.Live", code: failure, userInfo: [NSLocalizedDescriptionKey: "Live cleanup stop failed: \(failure)"])
        }
    }

    /// Core 认为这一路在播、宿主却没有播放器时的上报。
    /// 重进课后 Core 的 playing 可能还留着上一轮的流名，这时它只下发续签而不会重建
    /// 播放器，静默 return 会让两边永远对不上。报不可恢复停播让 Core 重新整路起播。
    /// 还在等渲染视图的路不算丢失，重试由适配器自己完成。
    private func reportMissingPlayer(streamName: String) {
        guard pendingStarts[streamName] == nil else { return }
        onEvent(.playStopped(
            streamName: streamName,
            recoverable: false,
            reason: LivePlayStopReason.hostStop
        ))
    }

    public func stopPlay(streamName: String) {
        guard Thread.isMainThread else {
            DispatchQueue.main.async { self.stopPlay(streamName: streamName) }
            return
        }
        pendingStarts.removeValue(forKey: streamName)
        guard let entry = players.removeValue(forKey: streamName) else {
            return
        }
        entry.player.setObserver(nil)
        streamNames.removeValue(forKey: ObjectIdentifier(entry.player))
        // 停播必须先摘渲染目标：容器会被 UI 跨会话复用，死播放器的渲染层留在
        // 容器里，下一轮的新播放器就画不进去，表现为重进课后永远不出画。
        entry.player.setRenderView(nil)
        entry.view = nil
        _ = entry.player.stopPlay()
    }

    public func stopAllPlay() {
        guard Thread.isMainThread else {
            DispatchQueue.main.async { self.stopAllPlay() }
            return
        }
        pendingStarts.removeAll()
        for streamName in Array(players.keys) {
            stopPlay(streamName: streamName)
        }
    }

    /// Rotation and sidebar visibility only replace/detach the render target;
    /// they must not stop the stream or its audio.
    /// 这一路还在等视图时，视图一到位立刻起播——不靠轮询，重进课的首画才不会拖。
    public func refreshRenderView(streamName: String) {
        guard Thread.isMainThread else {
            DispatchQueue.main.async { self.refreshRenderView(streamName: streamName) }
            return
        }
        if let pending = pendingStarts[streamName] {
            guard resolveView(streamName) != nil else { return }
            pendingStarts.removeValue(forKey: streamName)
            startPlay(pending.request)
            return
        }
        guard let entry = players[streamName] else { return }
        let view = resolveView(streamName)
        guard entry.view !== view else { return }
        entry.view = view
        entry.player.setRenderView(view)
    }

    private func streamName(of player: (any V2TXLivePlayerProtocol)?) -> String? {
        guard let player else { return nil }
        return streamNames[ObjectIdentifier(player)]
    }
}

extension TencentLiveIosAdapter: V2TXLivePlayerObserver {
    public func onVideoPlaying(
        _ player: any V2TXLivePlayerProtocol,
        firstPlay: Bool,
        extraInfo: [AnyHashable: Any]
    ) {
        guard let streamName = streamName(of: player) else { return }
        observe(streamName, "video_playing")
    }

    public func onAudioPlaying(
        _ player: any V2TXLivePlayerProtocol,
        firstPlay: Bool,
        extraInfo: [AnyHashable: Any]
    ) {
        guard let streamName = streamName(of: player) else { return }
        observe(streamName, "audio_playing")
    }

    private func observe(_ streamName: String, _ kind: String, code: Int32? = nil, message: String? = nil) {
        guard let entry = players[streamName] else { return }
        onEvent(.observation(streamName: streamName, playbackId: entry.request.playbackId, kind: kind, code: code, message: message))
    }
    public func onConnected(_ player: any V2TXLivePlayerProtocol, extraInfo: [AnyHashable: Any]) {
        guard let name = streamName(of: player) else { return }
        observe(name, "connected")
    }
    public func onVideoLoading(_ player: any V2TXLivePlayerProtocol, extraInfo: [AnyHashable: Any]) {
        guard let name = streamName(of: player) else { return }
        observe(name, "video_loading")
    }
    public func onAudioLoading(_ player: any V2TXLivePlayerProtocol, extraInfo: [AnyHashable: Any]) {
        guard let name = streamName(of: player) else { return }
        observe(name, "audio_loading")
    }
    public func onWarning(_ player: any V2TXLivePlayerProtocol, code: V2TXLiveCode, message: String, extraInfo: [AnyHashable: Any]) {
        guard let name = streamName(of: player) else { return }
        observe(name, "warning", code: Int32(code.rawValue), message: message)
    }

    public func onError(
        _ player: any V2TXLivePlayerProtocol,
        code: V2TXLiveCode,
        message: String,
        extraInfo: [AnyHashable: Any]
    ) {
        guard let streamName = streamName(of: player) else { return }
        observe(streamName, "error", code: Int32(code.rawValue), message: message)
    }

    public func onReceiveSeiMessage(_ player: any V2TXLivePlayerProtocol, payloadType: Int32, data: Data) {
        guard payloadType == 5, let livePlayer = player as? V2TXLivePlayer,
              let streamName = streamName(of: livePlayer),
              let serverMs = decodeEduSdkClockSei(data) else { return }
        onEvent(.sei(streamName: streamName, serverMs: serverMs))
    }

    public func onStatisticsUpdate(_ player: any V2TXLivePlayerProtocol, statistics: V2TXLivePlayerStatistics) {
        guard let livePlayer = player as? V2TXLivePlayer, let streamName = streamName(of: livePlayer) else { return }
        guard let entry = players[streamName] else { return }
        onEvent(.statistics(streamName: streamName, playbackId: entry.request.playbackId, metrics: [
            "downloadKbps": Int64(statistics.netSpeed),
            "audioBitrateKbps": Int64(statistics.audioBitrate),
            "videoBitrateKbps": Int64(statistics.videoBitrate),
            "fps": Int64(statistics.fps),
            "width": Int64(statistics.width),
            "height": Int64(statistics.height),
            "bufferDelayMs": Int64(statistics.jitterBufferDelay),
            "rttMs": Int64(statistics.rtt),
            "audioPacketLossPercent": Int64(statistics.audioPacketLoss),
            "videoPacketLossPercent": Int64(statistics.videoPacketLoss),
            "audioBlockTimeMs": Int64(statistics.audioTotalBlockTime),
            "videoBlockTimeMs": Int64(statistics.videoTotalBlockTime),
            "audioBlockRatePercent": Int64(statistics.audioBlockRate),
            "videoBlockRatePercent": Int64(statistics.videoBlockRate),
            "appCpuPercent": Int64(statistics.appCpu),
            "systemCpuPercent": Int64(statistics.systemCpu),
        ]))
    }
}

private func decodeEduSdkClockSei(_ data: Data) -> Int64? {
    let marker = Data([0x45, 0x64, 0x75, 0x53, 0x64, 0x6b, 0x43, 0x6c, 0x6f, 0x63, 0x6b, 0x00, 0x00, 0x00, 0x00, 0x01])
    guard let range = data.range(of: marker) else { return nil }
    guard let text = String(data: data.suffix(from: range.upperBound), encoding: .utf8),
          let jsonStart = text.firstIndex(of: "{"),
          let value = try? JSONSerialization.jsonObject(with: Data(text[jsonStart...].utf8)) as? [String: Any],
          (value["v"] as? NSNumber)?.intValue == 1,
          let serverMs = value["t"] as? NSNumber else { return nil }
    return serverMs.int64Value
}
